import React, { useState } from 'react';
import { toast } from 'react-toastify';
import adminService from '../services/adminService';
import '../styles/Components.css';

const StallApprovalForm = ({ stall, onApprovalComplete }) => {
  const [remarks, setRemarks] = useState('');
  const [loading, setLoading] = useState(false);
  const [actionType, setActionType] = useState(null); // 'approve' or 'reject'

  const handleApprove = async () => {
    setActionType('approve');
    setLoading(true);
    try {
      await adminService.approveStall(stall._id, { remarks });
      toast.success('Stall approved successfully!');
      setRemarks('');
      onApprovalComplete();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to approve stall');
    } finally {
      setLoading(false);
      setActionType(null);
    }
  };

  const handleReject = async () => {
    if (!remarks.trim()) {
      toast.warning('Please provide remarks for rejection');
      return;
    }

    setActionType('reject');
    setLoading(false);
    try {
      await adminService.rejectStall(stall._id, { remarks });
      toast.success('Stall rejected successfully!');
      setRemarks('');
      onApprovalComplete();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to reject stall');
    } finally {
      setLoading(false);
      setActionType(null);
    }
  };

  if (!stall) {
    return (
      <div className="stall-approval-form">
        <div className="no-selection">
          <p>Select a stall request to review</p>
        </div>
      </div>
    );
  }

  return (
    <div className="stall-approval-form">
      <div className="approval-header">
        <h3>Stall Approval Review</h3>
        <span className={`status-badge ${stall.approvalStatus}`}>
          {stall.approvalStatus?.toUpperCase()}
        </span>
      </div>

      <div className="stall-details-section">
        <div className="detail-row">
          <label>Stall Name:</label>
          <span className="detail-value">{stall.stallName}</span>
        </div>

        <div className="detail-row">
          <label>Category:</label>
          <span className="detail-value">
            {stall.category?.charAt(0).toUpperCase() + stall.category?.slice(1)}
          </span>
        </div>

        <div className="detail-row">
          <label>Size:</label>
          <span className="detail-value">
            {stall.size?.charAt(0).toUpperCase() + stall.size?.slice(1)}
          </span>
        </div>

        <div className="detail-row">
          <label>Location/Booth:</label>
          <span className="detail-value">{stall.location || 'Not specified'}</span>
        </div>

        <div className="detail-row">
          <label>Price (per day):</label>
          <span className="detail-value">LKR {stall.price?.toLocaleString() || '0'}</span>
        </div>

        {stall.description && (
          <div className="detail-row">
            <label>Description:</label>
            <span className="detail-value">{stall.description}</span>
          </div>
        )}

        {stall.organizer && (
          <div className="detail-row">
            <label>Organizer:</label>
            <span className="detail-value">{stall.organizer}</span>
          </div>
        )}

        {stall.requestedDate && (
          <div className="detail-row">
            <label>Requested Date:</label>
            <span className="detail-value">
              {new Date(stall.requestedDate).toLocaleDateString()}
            </span>
          </div>
        )}
      </div>

      <div className="remarks-section">
        <label htmlFor="approval-remarks">
          Remarks {stall.approvalStatus === 'rejected' && '*'}
        </label>
        <textarea
          id="approval-remarks"
          value={remarks}
          onChange={(e) => setRemarks(e.target.value)}
          placeholder={
            stall.approvalStatus === 'rejected'
              ? 'Rejection reason is required...'
              : 'Add remarks (optional)...'
          }
          rows={5}
          className="remarks-input"
        />
      </div>

      <div className="approval-action-buttons">
        <button
          className="btn-success"
          onClick={handleApprove}
          disabled={loading}
        >
          {actionType === 'approve' && loading ? 'Approving...' : '✓ Approve Stall'}
        </button>
        <button
          className="btn-danger"
          onClick={handleReject}
          disabled={loading}
        >
          {actionType === 'reject' && loading ? 'Rejecting...' : '✕ Reject Stall'}
        </button>
      </div>

      {stall.remarks && (
        <div className="previous-remarks">
          <h4>Previous Remarks:</h4>
          <p>{stall.remarks}</p>
        </div>
      )}
    </div>
  );
};

export default StallApprovalForm;
